use crate::aap::caps::http_client;
use crate::aap::caps::state_rw;
use crate::aap::caps::types::{FeedDocument, FetchFailure};

/// Hosts the node's HTTPClient handle is scoped to. A request outside this set
/// would trap at the boundary and take the whole tick down with it, so such
/// URLs are reported as failures instead of being requested.
const ALLOWED_HOSTS: [&str; 4] = [
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

/// Key under which each call's input is recorded in the shared store.
const LAST_INPUT_KEY: &str = "last-input";

struct Node;

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        // Record the input first, so it is stored even if a fetch later traps.
        state_rw::put(LAST_INPUT_KEY, &encode_input(&subscriptions));

        let mut documents = Vec::new();
        let mut failures = Vec::new();

        for url in subscriptions.urls {
            match host_of(&url) {
                Some(host) if is_allowed(&host) => match http_client::fetch(&url) {
                    Ok(body) => documents.push(FeedDocument { url, body }),
                    Err(error) => failures.push(FetchFailure { url, error }),
                },
                Some(host) => failures.push(FetchFailure {
                    url,
                    error: format!("host not in allowlist: {host}"),
                }),
                None => failures.push(FetchFailure {
                    url,
                    error: String::from("malformed url: expected http(s)://host/..."),
                }),
            }
        }

        FeedBatch { documents, failures }
    }
}

/// Encode the subscription list as `{"urls":[...]}`, so that what is stored can
/// be read back without ambiguity.
fn encode_input(subscriptions: &SubscriptionList) -> String {
    let mut out = String::from("{\"urls\":[");
    for (i, url) in subscriptions.urls.iter().enumerate() {
        if i > 0 {
            out.push(',');
        }
        push_json_string(&mut out, url);
    }
    out.push_str("]}");
    out
}

fn push_json_string(out: &mut String, s: &str) {
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 0x20 => {
                out.push_str(&format!("\\u{:04x}", c as u32));
            }
            c => out.push(c),
        }
    }
    out.push('"');
}

/// Extract the lowercase host from an http(s) URL, without userinfo or port.
fn host_of(url: &str) -> Option<String> {
    let trimmed = url.trim();
    let lower = trimmed.to_ascii_lowercase();
    let rest = if lower.starts_with("https://") {
        &trimmed[8..]
    } else if lower.starts_with("http://") {
        &trimmed[7..]
    } else {
        return None;
    };

    let authority_end = rest
        .find(|c| c == '/' || c == '?' || c == '#')
        .unwrap_or(rest.len());
    let authority = &rest[..authority_end];

    // Drop any userinfo ("user:pass@host").
    let host_port = match authority.rfind('@') {
        Some(i) => &authority[i + 1..],
        None => authority,
    };

    // Drop the port, if any. These hosts are never IPv6 literals.
    let host = match host_port.find(':') {
        Some(i) => &host_port[..i],
        None => host_port,
    };

    let host = host.trim_end_matches('.').to_ascii_lowercase();
    if host.is_empty() {
        None
    } else {
        Some(host)
    }
}

fn is_allowed(host: &str) -> bool {
    ALLOWED_HOSTS.iter().any(|allowed| *allowed == host)
}

export!(Node);
